59	// doImport opens the file, parses it, prints rows to stdout and errors to stderr.
60	// Returns exitCode (non-zero on file error).
61	func doImport(filename string) (int, error) {
62		file, err := os.Open(filename)
63		if err != nil {
64			return 1, fmt.Errorf("opening %q: %w", filename, err)
65		}
66		defer file.Close()
67	
68		rows, badRows, err := importer.ReadStock(file)
69		if err != nil {
70			return 1, err
71		}
72	
73		for _, row := range rows {
74			fmt.Printf("%s,%d,%s\n", row.Name, row.Quantity, row.Unit)
75		}
76	
77		for _, bad := range badRows {
78			fmt.Fprintf(os.Stderr, "%v\n", bad)
79		}
80	
81		return 0, nil
82	}
