12	func TestAcquire(t *testing.T) {
13		t.Parallel()
14	
15		t.Run("creates lock with pid", func(t *testing.T) {
16			t.Parallel()
17			dir := t.TempDir()
18			held, err := Acquire(dir)
19			if err != nil {
20				t.Fatal(err)
21			}
22			defer held.Release()
23			body, err := os.ReadFile(filepath.Join(dir, Name))
24			if err != nil || strings.TrimSpace(string(body)) != strconv.Itoa(os.Getpid()) {
25				t.Fatalf("lock body %q, err %v", body, err)
26			}
27		})
28	
29		t.Run("held lock names pid", func(t *testing.T) {
30			t.Parallel()
31			dir := t.TempDir()
32			if err := os.WriteFile(filepath.Join(dir, Name), []byte("4242\n"), 0o644); err != nil {
33				t.Fatal(err)
34			}
35			_, err := Acquire(dir)
36			if !errors.Is(err, ErrHeld) || !strings.Contains(err.Error(), "pid 4242") {
37				t.Fatalf("want ErrHeld naming pid 4242, got %v", err)
38			}
39		})
40	}
41	
42	func TestRelease(t *testing.T) {
43		t.Parallel()
44	
45		t.Run("removes lock", func(t *testing.T) {
46			t.Parallel()
47			dir := t.TempDir()
48			held, err := Acquire(dir)
49			if err != nil {
50				t.Fatal(err)
51			}
52			if err := held.Release(); err != nil {
53				t.Fatal(err)
54			}
55			if _, err := os.Stat(filepath.Join(dir, Name)); !errors.Is(err, os.ErrNotExist) {
56				t.Fatalf("lock still present: %v", err)
57			}
58		})
59	
60		t.Run("missing lock is ok", func(t *testing.T) {
61			t.Parallel()
62			held := &Lock{path: filepath.Join(t.TempDir(), Name)}
63			if err := held.Release(); err != nil {
64				t.Fatal(err)
65			}
66		})
67	}
